'AC-meta.dircov.1'; from __future__ import annotations; from pathlib import Path; from common.meta.extension import check_package_directory_coverage as gate; REPO_ROOT = Path(__file__).resolve().parents[2]
def _make_pkg_with_contract(root: Path, name: str) -> None: pkg = root / 'common' / name; pkg.mkdir(parents=True); (pkg / 'contract.py').write_text('\n'.join(['from common.meta.base.package_contract import PackageContract', '', 'CONTRACT = PackageContract(', f'    name="{name}",', '    klass="middleware",', '    status="draft",', '    depends_on=[],', '    interface=[],', '    events=[],', '    invariants=[],', '    roadmap=[],', ')', '']), encoding='utf-8')
def _make_bare_dir(root: Path, name: str, *, with_file: bool=True) -> None: pkg = root / 'common' / name; pkg.mkdir(parents=True); (pkg / 'some_tool.py').write_text('# a stray script\n', encoding='utf-8') if with_file else None
def test_real_repo_passes() -> None: errors = gate.check_directory_coverage(REPO_ROOT); assert errors == [], '\n'.join(errors); assert gate.UNGOVERNED_EXCEPTIONS == {}
def test_directory_with_contract_passes(tmp_path: Path) -> None: _make_pkg_with_contract(tmp_path, 'widgets'); assert gate.check_directory_coverage(tmp_path) == []
def test_contract_file_without_exported_contract_is_rejected(tmp_path: Path) -> None: pkg = tmp_path / 'common' / 'widgets'; pkg.mkdir(parents=True); (pkg / 'contract.py').write_text('contract = object()\n', encoding='utf-8'); errors = gate.check_directory_coverage(tmp_path); assert errors == ['common/widgets/contract.py does not export a module-level CONTRACT = PackageContract(...), so package discovery and governance cannot see it.']; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); _m2_pkg = _m2_tmp / 'common' / 'widgets'; _m2_pkg.mkdir(parents=True); (_m2_pkg / 'contract.py').write_text('CONTRACT = (\n', encoding='utf-8'); _m2_errors = gate.check_directory_coverage(_m2_tmp); assert _m2_errors == ['common/widgets/contract.py does not export a module-level CONTRACT = PackageContract(...), so package discovery and governance cannot see it.']; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); _m3_pkg = _m3_tmp / 'common' / 'widgets'; _m3_pkg.mkdir(parents=True); (_m3_pkg / 'contract.py').write_text('CONTRACT = object()\n', encoding='utf-8'); _m3_errors = gate.check_directory_coverage(_m3_tmp); assert _m3_errors == ['common/widgets/contract.py does not export a module-level CONTRACT = PackageContract(...), so package discovery and governance cannot see it.']; _m4_tmp = tmp_path / '_m4'; _m4_tmp.mkdir(exist_ok=True); _m4_pkg = _m4_tmp / 'common' / 'widgets'; _m4_pkg.mkdir(parents=True); (_m4_pkg / 'contract.py').write_text('\n'.join(['from common.meta.base.package_contract import PackageContract', '', 'CONTRACT: PackageContract = PackageContract(', '    name="widgets",', '    klass="middleware",', '    status="draft",', '    depends_on=[],', '    interface=[],', '    events=[],', '    invariants=[],', '    roadmap=[],', ')', '']), encoding='utf-8'); assert gate.check_directory_coverage(_m4_tmp) == []; _m5_tmp = tmp_path / '_m5'; _m5_tmp.mkdir(exist_ok=True); _make_bare_dir(_m5_tmp, 'random_junk'); _m5_errors = gate.check_directory_coverage(_m5_tmp); assert len(_m5_errors) == 1; assert 'common/random_junk/' in _m5_errors[0]; assert 'contract.py' in _m5_errors[0]; _m6_tmp = tmp_path / '_m6'; _m6_tmp.mkdir(exist_ok=True); (_m6_tmp / 'common' / '__pycache__').mkdir(parents=True); assert gate.check_directory_coverage(_m6_tmp) == []; _m7_tmp = tmp_path / '_m7'; _m7_tmp.mkdir(exist_ok=True); _m7_stale = _m7_tmp / 'common' / 'retired_pkg' / 'sub' / '__pycache__'; _m7_stale.mkdir(parents=True); (_m7_stale / 'mod.cpython-312.pyc').write_bytes(b'\x00'); assert gate.check_directory_coverage(_m7_tmp) == []; _m8_tmp = tmp_path / '_m8'; _m8_tmp.mkdir(exist_ok=True); _make_bare_dir(_m8_tmp, 'half_stale'); (_m8_tmp / 'common' / 'half_stale' / '__pycache__').mkdir(); _m8_errors = gate.check_directory_coverage(_m8_tmp); assert len(_m8_errors) == 1; assert _m8_errors[0].startswith('common/half_stale/')
def test_documented_exception_passes_without_contract(tmp_path: Path, monkeypatch) -> None: _make_bare_dir(tmp_path, 'wip_domain'); monkeypatch.setitem(gate.UNGOVERNED_EXCEPTIONS, 'wip_domain', 'test-only documented exception'); assert gate.check_directory_coverage(tmp_path) == []
def test_main_passes_quietly_on_real_repo(capsys) -> None: assert gate.main(['--repo-root', str(REPO_ROOT)]) == 0; assert 'PASSED' in capsys.readouterr().out
def test_main_fails_and_reports_on_a_junk_drawer(tmp_path: Path, capsys) -> None: _make_bare_dir(tmp_path, 'another_junk_drawer'); assert gate.main(['--repo-root', str(tmp_path)]) == 1; assert 'another_junk_drawer' in capsys.readouterr().err
